public sealed record OutboxMessage(Guid Id, string Type, string PayloadJson, DateTimeOffset CreatedAt);

public interface IOutboxStore
{
    Task AddAsync(OutboxMessage message, CancellationToken ct);
}

public interface IUnitOfWork
{
    Task SaveChangesAsync(CancellationToken ct);
}

public interface IOrderRepository
{
    void AddOrder(OrderDraft order);
}

public sealed record OrderDraft(Guid Id, decimal Total);

public sealed class OutboxDbContext : IUnitOfWork, IOutboxStore, IOrderRepository
{
    private readonly List<OrderDraft> _orders = new();
    private readonly List<OutboxMessage> _outbox = new();

    public void AddOrder(OrderDraft order) => _orders.Add(order);

    public Task AddAsync(OutboxMessage message, CancellationToken ct)
    {
        _outbox.Add(message);
        return Task.CompletedTask;
    }

    public async Task SaveChangesAsync(CancellationToken ct)
    {
        // Single transaction: orders + outbox rows commit together.
        await PersistAsync(_orders, _outbox, ct).ConfigureAwait(false);
    }

    private static Task PersistAsync(
        IReadOnlyList<OrderDraft> orders,
        IReadOnlyList<OutboxMessage> outbox,
        CancellationToken ct) => Task.CompletedTask;
}

public sealed class PlaceOrderService(IOrderRepository orders, IOutboxStore outbox, IUnitOfWork uow)
{
    public async Task PlaceAsync(OrderDraft order, CancellationToken ct)
    {
        orders.AddOrder(order);
        await outbox.AddAsync(new OutboxMessage(
            Guid.NewGuid(),
            "OrderPlaced",
            order.Id.ToString(),
            DateTimeOffset.UtcNow), ct).ConfigureAwait(false);
        await uow.SaveChangesAsync(ct).ConfigureAwait(false);
    }
}
